-- LEX ACTIVE foundation. Apply through Supabase migrations or the SQL editor.
-- Private source records are never used as public feed/profile rows.
begin;
create schema if not exists private;
revoke all on schema private from public;
grant usage on schema private to authenticated;
create table public.profiles (
 id uuid primary key references auth.users(id) on delete cascade,
 username text check (username ~ '^[a-zA-Z0-9_]{3,24}$'),
 display_name text not null default 'New member' check (length(display_name) between 1 and 80),
 bio text not null default '' check (length(bio)<=300), avatar_path text,
 created_at timestamptz not null default now()
);
create unique index profiles_username_ci on public.profiles(lower(username));
create table public.preferences (
 owner_id uuid primary key references auth.users(id) on delete cascade,
 theme text not null default 'Blush' check(theme in ('Blush','Classic','Midnight','Device')),
 units text not null default 'metric' check(units in ('metric','imperial')),
 leaderboard_opt_out boolean not null default false,
 notification_preferences jsonb not null default '{}'::jsonb,
 dashboard_sections text[] not null default '{}'
);
create function private.create_profile() returns trigger language plpgsql security definer set search_path='' as $$
begin insert into public.profiles(id) values(new.id);insert into public.preferences(owner_id) values(new.id);return new;end $$;
create trigger create_lex_profile after insert on auth.users for each row execute function private.create_profile();
create table public.blocks(owner_id uuid not null references auth.users(id) on delete cascade,blocked_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(owner_id,blocked_id),check(owner_id<>blocked_id));
create table public.friend_requests(id uuid primary key default gen_random_uuid(),sender_id uuid not null references auth.users(id) on delete cascade,recipient_id uuid not null references auth.users(id) on delete cascade,status text not null default 'pending' check(status in ('pending','accepted','declined','cancelled')),created_at timestamptz not null default now(),check(sender_id<>recipient_id));
create unique index one_pending_request on public.friend_requests(least(sender_id,recipient_id),greatest(sender_id,recipient_id)) where status='pending';
create table public.friendships(user_a uuid not null references auth.users(id) on delete cascade,user_b uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_a,user_b),check(user_a<user_b));
create table public.relationships(id uuid primary key default gen_random_uuid(),requester_id uuid not null references auth.users(id) on delete cascade,recipient_id uuid not null references auth.users(id) on delete cascade,tier text not null check(tier in ('close_friend','partner')),status text not null default 'pending' check(status in ('pending','accepted','declined','revoked')),check(requester_id<>recipient_id));
create table public.sharing_permissions(owner_id uuid not null references auth.users(id) on delete cascade,viewer_id uuid not null references auth.users(id) on delete cascade,category text not null check(category in ('training_history','nutrition_summary','food_diary','body_metrics','progress_photos','wellness','personal_notes','water','sleep')),created_at timestamptz not null default now(),primary key(owner_id,viewer_id,category),check(owner_id<>viewer_id));
create function private.not_blocked(target uuid) returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and not exists(select 1 from public.blocks where (owner_id=auth.uid() and blocked_id=target) or (owner_id=target and blocked_id=auth.uid())) $$;
create function private.is_friend(target uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.not_blocked(target) and exists(select 1 from public.friendships where user_a=least(auth.uid(),target) and user_b=greatest(auth.uid(),target)) $$;
create function private.can_read(owner uuid,category_name text) returns boolean language sql stable security definer set search_path='' as $$ select owner=auth.uid() or (private.is_friend(owner) and exists(select 1 from public.sharing_permissions where owner_id=owner and viewer_id=auth.uid() and category=category_name)) $$;
create function private.protect_identity() returns trigger language plpgsql set search_path='' as $$ declare col text;begin foreach col in array tg_argv loop if to_jsonb(old)->col is distinct from to_jsonb(new)->col then raise exception 'Record identity is immutable' using errcode='23514';end if;end loop;return new;end $$;
create table public.workout_sessions(owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,id uuid not null default gen_random_uuid(),name text not null check(length(name)<=100),date date not null,kind text not null default 'workout' check(kind in ('workout','exercise')),notes text not null default '',routine_id uuid,duration_seconds integer check(duration_seconds>=0),visibility text not null default 'private' check(visibility in ('private','friends')),primary key(owner_id,id));
alter table public.workout_sessions enable row level security;
create policy read_records on public.workout_sessions for select to authenticated using (private.can_read(owner_id,'training_history'));
create policy write_own on public.workout_sessions for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create trigger protect_identity before update on public.workout_sessions for each row execute function private.protect_identity('owner_id','id');
revoke all on public.workout_sessions from authenticated;
grant select on public.workout_sessions to authenticated;
revoke all on public.workout_sessions from anon;
