revoke all on public.workout_exercises from anon;
create index on public.workout_exercises(owner_id,session_id);
create table public.workout_sets(owner_id uuid not null default auth.uid() references auth.users(id) on delete cascade,id uuid not null default gen_random_uuid(),exercise_id uuid not null,position integer not null check(position>=0),weight numeric not null check(weight between 0 and 2000),reps integer not null check(reps between 1 and 1000),done boolean not null default true,set_type text not null default 'working' check(set_type in ('working','warmup','drop','failure','rest_pause','myo','partial')),rir numeric check(rir between 0 and 10),rpe numeric check(rpe between 0 and 10),duration_seconds integer check(duration_seconds>=0),notes text not null default '',foreign key(owner_id,exercise_id) references public.workout_exercises(owner_id,id) on delete cascade,primary key(owner_id,id));
