create policy own_profile on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create trigger protect_profile_id before update on public.profiles for each row execute function private.protect_identity('id');
revoke all on public.profiles from authenticated;
grant select,update on public.profiles to authenticated;revoke all on public.profiles from anon;
alter table public.blocks enable row level security;
create policy own_blocks on public.blocks for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
revoke all on public.blocks from authenticated;
grant select,insert,delete on public.blocks to authenticated;
alter table public.friendships enable row level security;
create policy participants on public.friendships for select to authenticated using(auth.uid() in (user_a,user_b));
revoke all on public.friendships from authenticated;
grant select,delete on public.friendships to authenticated;
create policy remove_friend on public.friendships for delete to authenticated using(auth.uid() in (user_a,user_b));
alter table public.friend_requests enable row level security;
create policy participants on public.friend_requests for select to authenticated using(auth.uid() in (sender_id,recipient_id) and private.not_blocked(case when sender_id=auth.uid() then recipient_id else sender_id end));
create policy send_request on public.friend_requests for insert to authenticated with check(sender_id=auth.uid() and status='pending' and private.not_blocked(recipient_id) and not private.is_friend(recipient_id));
revoke all on public.friend_requests from authenticated;
grant select,insert on public.friend_requests to authenticated;
alter table public.relationships enable row level security;
create policy participants on public.relationships for select to authenticated using(auth.uid() in (requester_id,recipient_id) and private.is_friend(case when requester_id=auth.uid() then recipient_id else requester_id end));
create policy request_relationship on public.relationships for insert to authenticated with check(requester_id=auth.uid() and status='pending' and private.is_friend(recipient_id));
revoke all on public.relationships from authenticated;
grant select,insert on public.relationships to authenticated;
alter table public.sharing_permissions enable row level security;
create policy own_grants on public.sharing_permissions for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid() and private.is_friend(viewer_id));
create policy received_grants on public.sharing_permissions for select to authenticated using(viewer_id=auth.uid() and private.is_friend(owner_id));
revoke all on public.sharing_permissions from authenticated;
grant select,insert,delete on public.sharing_permissions to authenticated;
create function public.respond_friend_request(request_id uuid,accept boolean) returns void language plpgsql security definer set search_path='' as $$ declare r public.friend_requests;begin
 select * into r from public.friend_requests where id=request_id for update;
 if r.id is null or r.recipient_id<>auth.uid() or r.status<>'pending' or not private.not_blocked(r.sender_id) then raise exception 'Request unavailable' using errcode='42501';end if;
 update public.friend_requests set status=case when accept then 'accepted' else 'declined' end where id=request_id;
 if accept then insert into public.friendships(user_a,user_b) values(least(r.sender_id,r.recipient_id),greatest(r.sender_id,r.recipient_id)) on conflict do nothing;end if;end $$;
create function public.cancel_friend_request(request_id uuid) returns void language plpgsql security definer set search_path='' as $$begin update public.friend_requests set status='cancelled' where id=request_id and sender_id=auth.uid() and status='pending';end $$;
create function private.on_block() returns trigger language plpgsql security definer set search_path='' as $$begin
 delete from public.friendships where user_a=least(new.owner_id,new.blocked_id) and user_b=greatest(new.owner_id,new.blocked_id);
 delete from public.sharing_permissions where (owner_id=new.owner_id and viewer_id=new.blocked_id) or(owner_id=new.blocked_id and viewer_id=new.owner_id);
 update public.friend_requests set status='cancelled' where status='pending' and ((sender_id=new.owner_id and recipient_id=new.blocked_id)or(sender_id=new.blocked_id and recipient_id=new.owner_id));
 update public.relationships set status='revoked' where (requester_id=new.owner_id and recipient_id=new.blocked_id)or(requester_id=new.blocked_id and recipient_id=new.owner_id);
 return new;end $$;
create trigger block_revokes_access after insert on public.blocks for each row execute function private.on_block();
create function private.on_unfriend() returns trigger language plpgsql security definer set search_path='' as $$begin
 delete from public.sharing_permissions where (owner_id=old.user_a and viewer_id=old.user_b) or(owner_id=old.user_b and viewer_id=old.user_a);
 update public.relationships set status='revoked' where (requester_id=old.user_a and recipient_id=old.user_b)or(requester_id=old.user_b and recipient_id=old.user_a);return old;end $$;
create trigger unfriend_revokes_grants after delete on public.friendships for each row execute function private.on_unfriend();
revoke execute on all functions in schema private from public,anon;
grant execute on function private.not_blocked(uuid),private.is_friend(uuid),private.can_read(uuid,text) to authenticated;
revoke execute on function public.respond_friend_request(uuid,boolean),public.cancel_friend_request(uuid) from public,anon;
grant execute on function public.respond_friend_request(uuid,boolean),public.cancel_friend_request(uuid) to authenticated;
commit;
